[
  {
    "sys_consequence_reasoning": "five people are about to be hit, and the lever costs nobody anything",
    "sys_contextual_flexibility": "caution exists to prevent accidents, and here it would cause one",
    "pda_emotion_identification_difficulty": "What I'd actually feel in that moment, I can't say",
    "pda_other_regret_expectation": "anyone who froze and just watched would regret holding back"
  },
  {
    "pda_emotion_identification_difficulty": "tried picturing my reaction and can't pin it down",
    "sys_contextual_flexibility": "habit makes sense when meddling carries risk. Here the siding is empty",
    "sys_consequence_reasoning": "no downside to weigh against five lives",
    "pda_other_regret_expectation": "One of the workers might later wish he'd checked the line"
  },
  {
    "sys_contextual_flexibility": "warning was always about keeping people safe, and here obeying it does the opposite",
    "pda_other_regret_expectation": "Whoever left that train able to roll will probably regret it",
    "pda_emotion_identification_difficulty": "As for my own feelings, hard to say"
  },
  {
    "sys_contextual_flexibility": "reason disappears when stepping in harms no one",
    "pda_other_regret_expectation": "someone beside me talked me out of it, I think that person would regret",
    "pda_emotion_identification_difficulty": "My own reaction is harder to read"
  },
  {
    "sys_consequence_reasoning": "Five workers on one side, an empty siding with a barrier on the other",
    "sys_contextual_flexibility": "because I could hurt someone by mistake, and here I can't",
    "pda_other_regret_expectation": "I doubt the workers would regret being out there",
    "ce_contextual_explanation": "They had no reason to expect a runaway train",
    "pda_emotion_identification_difficulty": "Me, I'm honestly not sure what I'd feel"
  },
  {
    "sys_contextual_flexibility": "Here nobody does, so the usual reluctance to intervene doesn't really apply",
    "sys_consequence_reasoning": "The whole trade-off is five people safe versus a train stopped",
    "pda_other_regret_expectation": "whoever built that siding wouldn't regret the effort",
    "pda_emotion_identification_difficulty": "What's going on in me emotionally is murky"
  },
  {
    "sys_contextual_flexibility": "waiting would mean five people get hit while I stand there being polite",
    "pda_other_regret_expectation": "might kick himself later",
    "pda_emotion_identification_difficulty": "I genuinely don't know what to call it"
  },
  {
    "sys_contextual_flexibility": "there's no risk to anyone and five lives are at stake, and the instruction stops fitting",
    "pda_other_regret_expectation": "bystander who knew how the lever worked and didn't use it would... carry that",
    "pda_emotion_identification_difficulty": "Inside, I'm not sure what's happening with me"
  },
  {
    "sys_consequence_reasoning": "five injured or killed workers against a train harmlessly stopped",
    "sys_contextual_flexibility": "Here they can't choose, and the choice only helps them",
    "pda_other_regret_expectation": "I don't think any of the workers would regret trusting",
    "ce_contextual_explanation": "They couldn't have known",
    "pda_emotion_identification_difficulty": "My own reaction is hard to label"
  },
  {
    "sys_contextual_flexibility": "With that much certainty and five people in the way, holding back would be the reckless",
    "pda_other_regret_expectation": "If a friend were with me and argued against it, I think she'd come to regret",
    "pda_emotion_identification_difficulty": "What I'd feel, I can't quite say"
  }
]
